<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'; import { useRouter } from 'vue-router'; import { MessageSquare, ShieldCheck } from '@lucide/vue'; import { api, type ReviewItem } from '../lib/api'; import { useSessionStore } from '../stores/session'
const session=useSessionStore();const router=useRouter();const items=ref<ReviewItem[]>([]);const filter=ref('all');const filtered=computed(()=>items.value.filter(i=>(filter.value==='all'||i.status===filter.value)&&(i.brandId===session.brandId)));onMounted(async()=>items.value=await api.reviews())
</script>
<template><div class="page-stack"><section class="page-title-row"><div><p class="eyebrow">TEAM REVIEW</p><h2>審核中心</h2><p>集中處理待核准與退回修改的平台內容。</p></div><div class="segmented"><button :class="{active:filter==='all'}" @click="filter='all'">全部</button><button :class="{active:filter==='in_review'}" @click="filter='in_review'">待審核</button><button :class="{active:filter==='changes_requested'}" @click="filter='changes_requested'">待修改</button></div></section><section class="panel"><div v-if="filtered.length" class="review-queue"><button v-for="item in filtered" :key="item.variantId" @click="router.push(`/campaigns/${item.campaignId}/posts/${item.postId}`)"><span class="platform-badge">{{item.platform}}</span><div><strong>{{item.postTitle}}</strong><p>{{item.campaignName}} · {{item.brandName}}</p></div><span v-if="item.openCommentCount"><MessageSquare :size="15"/>{{item.openCommentCount}}</span><i class="status-chip" :class="item.status">{{item.status}}</i><small>{{new Date(item.updatedAt).toLocaleDateString('zh-TW')}}</small></button></div><div v-else class="empty-block large"><ShieldCheck/><h3>審核佇列已清空</h3><p>目前沒有需要處理的內容。</p></div></section></div></template>
